package app.multimin.ui;
import javax.swing.*;import java.awt.*;import java.lang.reflect.*;
public class GuiHelpersCheck {
 static int verify(Container root,boolean expected){int count=0;for(Component c:root.getComponents()){if(c instanceof JComponent j&&Boolean.TRUE.equals(j.getClientProperty("gui.helper"))){if(j.isVisible()!=expected)throw new AssertionError("Helper visibility");count++;}if(c instanceof Container p)count+=verify(p,expected);}return count;}
 public static void main(String[] args)throws Exception{SwingUtilities.invokeAndWait(()->{MainWindow w=null;try{AppPreferences p=new AppPreferences();if(!p.getBoolean("guiHelpers",true))throw new AssertionError("Expected default on in isolated profile");w=new MainWindow(new app.multimin.backend.PythonBridge());Field f=MainWindow.class.getDeclaredField("preferences");f.setAccessible(true);p=(AppPreferences)f.get(w);Method refresh=MainWindow.class.getDeclaredMethod("refreshTheme");refresh.setAccessible(true);if(verify(w,true)!=2)throw new AssertionError("Missing helper groups");p.putBoolean("guiHelpers",false);refresh.invoke(w);verify(w,false);if(new AppPreferences().getBoolean("guiHelpers",true))throw new AssertionError("Not persisted");p.putBoolean("guiHelpers",true);refresh.invoke(w);verify(w,true);System.out.println("PASS: helpers default on, hide both groups, persist and restore");}catch(Exception e){throw new RuntimeException(e);}finally{if(w!=null){try{Method stop=MainWindow.class.getDeclaredMethod("shutdownServices");stop.setAccessible(true);stop.invoke(w);}catch(Exception e){throw new RuntimeException(e);}w.dispose();}}});}
}
